    [<Fact>]
    let ``each pinned capture case reads its Debug value, or Release refuses it as pinned`` () =
        let release =
#if DEBUG
            false
#else
            true
#endif
        let failures =
            [ for name, run, expected, refused in pinned do
                Ticks.Reset()
                match (try Ok(run (box (CaptureEcho()))) with :? DlrTranslationException as e -> Error e.Message) with
                | Ok value when value <> expected -> yield sprintf "%s: %s, not %s" name value expected
                | Ok _ when release && refused -> yield sprintf "%s: now runs in Release (pinned as refused)" name
                | Error message when not (release && refused) -> yield sprintf "%s: %s" name message
                | _ -> () ]
        failures |> should be Empty
